--
-- Table structure for table `supplier_ledgers`
--

DROP TABLE IF EXISTS `supplier_ledgers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `supplier_ledgers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `supplier_id` bigint unsigned NOT NULL,
  `type` enum('opening_balance','purchase','payment','adjustment','return') COLLATE utf8mb3_unicode_ci NOT NULL,
  `purchase_id` bigint unsigned DEFAULT NULL,
  `purchase_payment_id` bigint unsigned DEFAULT NULL,
  `purchase_return_id` bigint unsigned DEFAULT NULL,
  `payable_added` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Amount owed added',
  `payment_made` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Amount paid',
  `balance` decimal(15,2) NOT NULL COMMENT 'Running balance - amount we owe',
  `description` text COLLATE utf8mb3_unicode_ci,
  `reference_number` varchar(191) COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `date` date NOT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `supplier_ledgers_purchase_payment_id_foreign` (`purchase_payment_id`),
  KEY `supplier_ledgers_created_by_foreign` (`created_by`),
  KEY `supplier_ledgers_supplier_id_date_index` (`supplier_id`,`date`),
  KEY `supplier_ledgers_purchase_id_date_index` (`purchase_id`,`date`),
  KEY `supplier_ledgers_type_index` (`type`),
  KEY `supplier_ledgers_supplier_id_purchase_id_type_index` (`supplier_id`,`purchase_id`,`type`),
  KEY `supplier_ledgers_purchase_return_id_foreign` (`purchase_return_id`)
) ENGINE=MyISAM AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

